func newTestRouter(t *testing.T) (*httptest.Server, func()) {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "api.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	server := httptest.NewServer(NewRouter(st))
	return server, func() {
		server.Close()
		st.Close()
	}
}

func doJSON(t *testing.T, method, url string, body any) (*http.Response, map[string]any) {
	t.Helper()
	var reader *bytes.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		reader = bytes.NewReader(raw)
	} else {
		reader = bytes.NewReader(nil)
	}
	request, err := http.NewRequest(method, url, reader)
	if err != nil {
		t.Fatalf("request: %v", err)
	}
	request.Header.Set("Content-Type", "application/json")
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		t.Fatalf("do: %v", err)
	}
	var decoded map[string]any
	_ = json.NewDecoder(response.Body).Decode(&decoded)
	response.Body.Close()
	return response, decoded
}

func doRaw(t *testing.T, method, url, raw string) (*http.Response, map[string]any) {
	t.Helper()
	request, err := http.NewRequest(method, url, bytes.NewBufferString(raw))
	if err != nil {
		t.Fatalf("request: %v", err)
	}
	request.Header.Set("Content-Type", "application/json")
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		t.Fatalf("do: %v", err)
	}
	var decoded map[string]any
	_ = json.NewDecoder(response.Body).Decode(&decoded)
	response.Body.Close()
	return response, decoded
}

func createJob(t *testing.T, base string, body map[string]any) map[string]any {
	t.Helper()
	response, decoded := doJSON(t, http.MethodPost, base+"/api/v1/jobs", body)
	if response.StatusCode != http.StatusCreated {
		t.Fatalf("create status = %d, body = %v", response.StatusCode, decoded)
	}
	return decoded
}

func errorCode(t *testing.T, decoded map[string]any) string {
	t.Helper()
	errorObject, ok := decoded["error"].(map[string]any)
	if !ok {
		t.Fatalf("missing error object: %v", decoded)
	}
	code, _ := errorObject["code"].(string)
	message, _ := errorObject["message"].(string)
	if code == "" || message == "" {
		t.Fatalf("error missing code/message: %v", errorObject)
	}
	if len(errorObject) != 2 {
		t.Fatalf("error object has extra fields: %v", errorObject)
	}
	return code
}

func TestCreateJobLifecycle(t *testing.T) {
	server, cleanup := newTestRouter(t)
	defer cleanup()

	before := time.Now().UTC()
	job := createJob(t, server.URL, map[string]any{
		"name":       "daily-report",
		"expression": "0 9 * * *",
		"timezone":   "Asia/Shanghai",
		"enabled":    true,
	})

	for _, field := range []string{"id", "name", "expression", "timezone", "enabled", "created_at", "next_run"} {
		if _, ok := job[field]; !ok {
			t.Fatalf("response missing %q: %v", field, job)
		}
	}
	if job["name"] != "daily-report" || job["expression"] != "0 9 * * *" ||
		job["timezone"] != "Asia/Shanghai" || job["enabled"] != true {
		t.Fatalf("unexpected fields: %v", job)
	}

	createdAt, err := time.Parse(time.RFC3339, job["created_at"].(string))
	if err != nil {
		t.Fatalf("created_at: %v", err)
	}
	if createdAt.Location() != time.UTC && createdAt.Format("-07:00") != "+00:00" {
		t.Fatalf("created_at not UTC: %s", createdAt)
	}
	if createdAt.Before(before.Add(-time.Second)) || createdAt.After(time.Now().UTC().Add(time.Second)) {
		t.Fatalf("created_at out of range: %s", createdAt)
	}

	nextText := job["next_run"].(string)
	nextRun, err := time.Parse(time.RFC3339, nextText)
	if err != nil {
		t.Fatalf("next_run: %v", err)
	}
	if !nextRun.After(time.Now()) {
		t.Fatalf("next_run %s must be strictly after now", nextRun)
	}
	// 09:00 Shanghai equals 01:00 UTC.
	if nextRun.Hour() != 1 || nextRun.Minute() != 0 {
		t.Fatalf("next_run wall time = %s, want 01:00 UTC", nextRun)
	}
}

