func TestCreateValidationErrors(t *testing.T) {
	server, cleanup := newTestRouter(t)
	defer cleanup()

	cases := []struct {
		name       string
		body       string
		wantStatus int
		wantCode   string
	}{
		{"invalid json", `{not json`, http.StatusBadRequest, "invalid_json"},
		{"trailing json", `{"name":"a"} {"name":"b"}`, http.StatusBadRequest, "invalid_json"},
		{"empty body", ``, http.StatusBadRequest, "invalid_json"},
		{"empty name", `{"name":"   ","expression":"0 9 * * *","timezone":"UTC","enabled":true}`, http.StatusUnprocessableEntity, "name_required"},
		{"missing name", `{"expression":"0 9 * * *","timezone":"UTC","enabled":true}`, http.StatusUnprocessableEntity, "name_required"},
		{"bad expression", `{"name":"n","expression":"99 * * * *","timezone":"UTC","enabled":true}`, http.StatusUnprocessableEntity, "schedule_invalid"},
		{"impossible expression", `{"name":"n","expression":"0 0 30 2 *","timezone":"UTC","enabled":true}`, http.StatusUnprocessableEntity, "schedule_invalid"},
		{"bad timezone", `{"name":"n","expression":"0 9 * * *","timezone":"Mars/Olympus","enabled":true}`, http.StatusUnprocessableEntity, "timezone_invalid"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			response, decoded := doRaw(t, http.MethodPost, server.URL+"/api/v1/jobs", tc.body)
			if response.StatusCode != tc.wantStatus {
				t.Fatalf("status = %d, want %d (%v)", response.StatusCode, tc.wantStatus, decoded)
			}
			if code := errorCode(t, decoded); code != tc.wantCode {
				t.Fatalf("code = %q, want %q", code, tc.wantCode)
			}
		})
	}
}

