	response, patched = doJSON(t, http.MethodPatch, server.URL+"/api/v1/jobs/"+id, map[string]any{
		"enabled": true,
	})
	if response.StatusCode != http.StatusOK || patched["enabled"] != true || patched["next_run"] == nil {
		t.Fatalf("enable: %d %v", response.StatusCode, patched)
	}

