		"name": "rolling-renamed",
	})
	if response.StatusCode != http.StatusOK || patched["name"] != "rolling-renamed" || patched["next_run"] == nil {
		t.Fatalf("rename: %d %v", response.StatusCode, patched)
	}

	// DELETE.
	response, _ = doJSON(t, http.MethodDelete, server.URL+"/api/v1/jobs/"+id, nil)
	if response.StatusCode != http.StatusNoContent {
		t.Fatalf("delete status = %d", response.StatusCode)
	}
	response, decoded := doJSON(t, http.MethodGet, server.URL+"/api/v1/jobs/"+id, nil)
	if response.StatusCode != http.StatusNotFound || errorCode(t, decoded) != "job_not_found" {
